  flow.innerHTML=`<h2>資本家プレイヤーの手番</h2><p class="setup-summary">実物カードで行動を選び、対応するボタンで盤面を更新します。</p><div class="buttons"><button id="capBuild">企業を設立</button><button id="capPressure" class="quiet">政治的圧力</button><button id="capLobby" class="quiet">ロビー</button></div><details><summary>政策を提議</summary>${available.length?`<label>政策<select id="capPolicy">${available.map(id=>`<option value="${id}">政策${id}（現在${state.positions[id]}）</option>`).join('')}</select></label><label>提議先<select id="capPolicyTarget"></select></label><p class="muted">通常は隣接区画です。カード効果で2区画先を指定する場合も記録できます。</p><label><input id="capImmediate" type="checkbox">影響力1を支払い即時投票する</label><p id="capVote" class="notice" hidden>提議後、共通の即時投票ウインドウへ進みます。</p><button id="capPropose">提議を記録</button>`:'<p class="muted">提議できる政策がありません。</p>'}</details><details><summary>商品を購入・商取引</summary><label>購入先<select id="capPurchaseSource"><option value="Foreign">海外市場</option><option value="BusinessDeal">商取引カード</option></select></label><div id="capPurchaseFields"></div><button id="capPurchase">購入を記録</button></details><details><summary>賃金を調整（フリー）</summary>${wageCompanies.length?`<label>企業<select id="capWageCompany">${wageCompanies.map(([id,c])=>`<option value="${id}">${esc(defs[id].name_jp)}（現在${wageText(defs[id],c.wage)}）</option>`).join('')}</select></label><label>新しい賃金<select id="capWageTarget"></select></label><p class="muted">賃金を上げると労働者は誓約中になります。誓約中の労働者がいる企業では下げられません。政策2の最低賃金を守ります。</p><button id="capRaiseWage">賃金を変更</button>`:'<p class="muted">賃金を調整できる企業がありません。</p>'}</details><details><summary>企業を売却</summary>${sellable.length?`<label>企業<select id="capSellCompany">${sellable.map(([id])=>`<option value="${id}">${esc(defs[id].name_jp)}（売却額${defs[id].cost}）</option>`).join('')}</select></label><p class="muted">労働者を失業者エリアへ戻し、企業費用と同額を収入へ加えます。</p><button id="capSell">売却を記録</button>`:'<p class="muted">誓約中の労働者がいない売却可能な企業はありません。</p>'}</details><details><summary>海外市場へ売却</summary><label>商品<select id="capExportResource"><option value="food">食料</option><option value="luxury">ぜいたく品</option><option value="health">医療</option><option value="education">教育</option></select></label><div class="grid"><label>支払う数量<input id="capExportQty" type="number" min="1" value="1"></label><label>輸出カードの収入<input id="capExportRevenue" type="number" min="0" value="0"></label></div><button id="capExport">輸出を記録</button></details><p class="muted">収入${cap.revenue}／資本${cap.capital}／貸付金${cap.loans}。通常支払いは収入→資本、ロビーは資本→収入、不足時は貸付金を使います。</p><button id="playerEnd" class="quiet">資本家の手番を終了</button>`;
  $('capBuild').onclick=()=>WCARecords.openCapitalistBuild();$('capPressure').onclick=()=>act({type:'playerPressure'});$('capLobby').onclick=()=>act({type:'playerLobby'});if($('capRaiseWage')){const wageTargets=()=>{const c=state.records.companies[$('capWageCompany').value],levels=['L1','L2','L3'].filter(x=>x!==c.wage&&({L1:1,L2:2,L3:3})[x]>=({A:3,B:2,C:1})[state.positions['2']]&&((({L1:1,L2:2,L3:3})[x]>({L1:1,L2:2,L3:3})[c.wage])||!c.slots.some(slot=>slot.committed)));$('capRaiseWage').disabled=!levels.length;$('capWageTarget').innerHTML=options(levels,levels[0],Object.fromEntries(levels.map(level=>[level,wageText(defs[$('capWageCompany').value],level)])));};$('capWageCompany').onchange=wageTargets;wageTargets();$('capRaiseWage').onclick=()=>act({type:'capitalistFree',plan:{action:'WAGE',id:$('capWageCompany').value,wage:$('capWageTarget').value}});}if($('capSell'))$('capSell').onclick=()=>act({type:'playerSell',id:$('capSellCompany').value});$('capExport').onclick=()=>act({type:'playerExport',resource:$('capExportResource').value,qty:Number($('capExportQty').value),revenue:Number($('capExportRevenue').value)});
