 const present=Object.keys(state.records?.participants||{}).filter(id=>state.records.participants[id]!=='absent'),proposerOptions=present.map(id=>`<option value="${id}">${participantLabel(state,id)}</option>`).join('');
 $('events').innerHTML=`<details><summary>手動補正</summary>${legacy.length?`<p class="notice">更新前に提議された政策${legacy.map(([id])=>id).join('・')}は提議先が保存されていません。以下から結果と位置を入力してください。</p>`:''}<div class="grid"><label>政策<select id="policyId">${options(['1','2','3','4','5','6','7'],'1')}</select></label><label>提議先・新しい位置<select id="position">${options(['A','B','C'],state.positions['1'])}</select></label></div><label>提議者<select id="policyProposer">${proposerOptions}</select></label><label>イベント<select id="result"><option value="position">施行位置だけを訂正</option><option value="pending">法案を提議（投票待ち）</option><option value="failed">投票・否決</option><option value="passed">投票・可決</option></select></label><button id="policyApply" class="quiet" ${locked?'disabled':''}>政策イベントを記録</button><p class="source">確認済み位置：${Object.entries(state.positions).map(([k,v])=>k+v).join(' / ')}</p><div class="buttons"><button id="demResolve" class="quiet" ${!['start','card','end'].includes(state.phase)||!state.aside.actions.DEM||!state.records?.common?.tokens?.demonstration?'disabled':''}>デモを手動解決</button></div></details>`;
