 const policies=Object.keys(state.positions).filter(id=>!state.proposals[id]);
 flow.innerHTML=`<h2>労働者プレイヤーの手番</h2><p class="setup-summary">実物のアクションカードを1枚捨て、基本アクションを1つ実行してください。</p>${state.workingBasicUsed?'<p class="setup-summary">この手番の基本アクションは実行済みです。</p>':`<details><summary>労働者の割り当て</summary><p>失業労働者を合計3人まで、企業または労働組合へ配置します。企業は全スロットを同時に埋め、配置した労働者は誓約中になります。</p>${vacant.map(([id,c])=>`<fieldset><label><input type="checkbox" data-working-company="${id}">${esc(defs[id].name_jp)}</label>${c.slots.map((slot,i)=>{const req=defs[id].workers[i];return `<label>スロット${i+1}<select data-working-slot="${id}" data-index="${i}">${Object.entries(skillNames).filter(([key])=>req.type!=='Skilled'||req.color===key).map(([key,label])=>`<option value="${key}">${label}（失業${r.common.unemployed.Working[key]||0}人）</option>`).join('')}</select></label>`;}).join('')}</fieldset>`).join('')}${Object.entries(industryNames).filter(([id])=>!r.personal.Working.unions[id]).map(([id,label])=>`<label><input type="checkbox" data-working-union="${id}">${label}の労働組合を設立（同産業に労働者4人・対応する熟練失業者1人、+2VP）</label>`).join('')}<button id="workingAssign">割り当てを反映</button></details>
 <details><summary>商品・サービスの購入</summary><label>資源<select id="workingResource"><option value="food">食料</option><option value="health">医療</option><option value="education">教育</option><option value="luxury">ぜいたく品</option></select></label><p>購入先ごとに人口${w.population}個まで。同じ資源を複数の購入先から購入できます。</p><div id="workingSources"></div><p id="workingCost" class="setup-summary"></p><button id="workingBuy">購入を反映</button></details>
 <details><summary>法案提議</summary>${policies.length?`<label>政策<select id="workingPolicy">${policies.map(id=>`<option value="${id}">政策${id}（現在${state.positions[id]}）</option>`).join('')}</select></label><label>提議先<select id="workingTarget"></select></label><label><input type="checkbox" id="workingImmediate">影響力1を使い即時投票</label><button id="workingPropose">法案を提議</button>`:'<p>提議できる政策がありません。</p>'}</details>
 <details><summary>ストライキ</summary><p>1〜2社を選択します。対象の労働者は誓約中になります。</p>${strike.map(([id])=>`<label><input type="checkbox" data-working-strike="${id}">${esc(defs[id].name_jp)}</label>`).join('')||'<p>ストライキできる企業がありません。</p>'}<button id="workingStrike" ${strike.length?'':'disabled'}>ストライキを実施</button></details>
 <div class="buttons"><button id="workingDem" ${WCARecords.demonstrationStatus(r).eligible&&!r.common.tokens.demonstration?'':'disabled'}>デモを実施</button><button id="workingPressure">政治的圧力（投票駒3個を袋へ）</button></div>`}<p class="source">基本ルール：労働者階級の基本アクション。${state.playerCards?'対応済みのカード効果は上の手札から実行できます。':'カード固有の効果は実物で処理し、盤面タブに記録してください。'}</p><button id="playerEnd">労働者の手番を終了</button>`;
 $('playerEnd').onclick=()=>act({type:'playerEnd'});renderWorkingFreeActions(flow);if(state.workingBasicUsed)return;
 const run=plan=>act({type:'workingBasic',plan});
